    // END MACHINE VECTORS
    public static int run()throws Exception{
        count=0;check(VECTORS.length==62,"Native UI raster program count");Owner sample=null;
        for(String vector:VECTORS){DataInputStream in=new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(vector))));String name=in.readUTF();int x=in.readInt(),y=in.readInt(),value=in.readInt();boolean shrink=in.readBoolean();Snapshot initial=snapshot(in);Owner owner=new Owner(initial,x,y,value,shrink);sample=owner;int operations=in.readInt();String error=null;for(int n=0;n<operations;n++){String op=in.readUTF();int[] args=ints(in);if(error==null)try{owner.operation(op,args);}catch(IOException failure){error=failure.getMessage();}}Snapshot expected=snapshot(in);String boundary=in.readUTF();check(boundary.isEmpty()?error==null:error!=null,"Native owner boundary "+name+" "+error);owner.compare(expected,name);if(name.equals("button_text_raw_expand"))check(owner.glyphBacking.get(0).length==80+220*104,"Shared raw text retains entire actually known following owner bytes");if(name.equals("encoded_caption_no_macro"))check(owner.glyphBacking.get(0).length==5,"Caption stack exposes only its written prefix plus oneNUL");}
        final Owner owner=sample;Pc1UiRaster missing=new Pc1UiRaster(owner.ui,owner.compositor,null);owner.ui.writeInt(Pc1NativeUi.BUTTON_COUNT,0);long before=owner.compositor.invalidationSerial();missing.buttons(0);check(owner.compositor.invalidationSerial()==before+1,"Empty buttons still invalidate without unused callbacks");reject(()->missing.buttons(1),"consumer40a5b0");reject(()->missing.redrawGrid(0,0,88,96),"consumer415d50");
        return count;
    }
    public static void main(String[] args)throws Exception{System.out.println("PC1 raw UI raster assertions: "+run());}
